def countSubstring(S: str) -> int:
    count = 0
    balance = 0
    prefix_count = {0: 1}

    for char in S:
        if char == '1':
            balance += 1
        else:
            balance -= 1

        if balance > 0:
            count += balance
        else:
            count += max(0, prefix_count.get(balance - 1, 0))

        prefix_count[balance] = prefix_count.get(balance, 0) + 1

    return count
